const portfolioDay=value=>Date.parse(value+'T12:00:00Z'),portfolioIso=value=>new Date(value).toISOString().slice(0,10);
function portfolioStatus(item){const progress=currentStageStatus(item);if(item.lifecycle==='draft')return{state:'setup',text:'Draft setup'};if(item.lifecycle==='completed')return{state:'complete',text:`Completed${item.completedOn?' '+date(item.completedOn):''}`};if(!progress.tracking)return{state:'setup',text:'Tracking not started'};return{state:progress.state||'setup',text:progress.state==='complete'?'Programme complete':`${progress.current?.name??'Project'} · ${progress.label}`}}
function portfolioModel(items){const timeZone=items.find(item=>item.workflow?.timeZone)?.workflow?.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',today=todayInTimeZone(timeZone),rows=items.map(item=>{upgradeProject(item);const plan=stages(item);return{item,index:projects.indexOf(item),plan,start:plan[0].start,end:plan.at(-1).end,status:portfolioStatus(item)}}).sort((a,b)=>a.start.localeCompare(b.start)||a.end.localeCompare(b.end));let first=Math.min(portfolioDay(today),...rows.map(row=>portfolioDay(row.start))),last=Math.max(portfolioDay(today),...rows.map(row=>portfolioDay(row.end))),span=Math.max(86400000,last-first),padding=Math.max(2,Math.ceil(span/86400000*.04))*86400000;first-=padding;last+=padding;const position=value=>Math.max(0,Math.min(100,(portfolioDay(value)-first)/(last-first)*100)),ticks=Array.from({length:6},(_,index)=>{const value=first+(last-first)*(index/5);return{date:portfolioIso(value),position:index*20}});return{rows,today,start:portfolioIso(first),end:portfolioIso(last),position,ticks}}
