function portfolioMarkup(items){const model=portfolioModel(items),active=model.rows.filter(row=>row.item.lifecycle==='active').length,drafts=model.rows.filter(row=>row.item.lifecycle==='draft').length,axis=model.ticks.map(tick=>`<span style="--position:${tick.position}%">${date(tick.date)}</span>`).join(''),grid=model.ticks.map(tick=>`<i style="--position:${tick.position}%"></i>`).join(''),today=model.position(model.today),archived=projectFilter==='archived',heading=archived?'Archived projects':'Your programme',intro=archived?'Their original programme remains visible for reference.':'Every project on the same timeline. Overlaps show where the work is busiest.',summary=archived?`<span><b>${items.length}</b> archived</span>`:`<span><b>${items.length}</b> project${items.length===1?'':'s'}</span><span><b>${active}</b> active</span>${drafts?`<span><b>${drafts}</b> draft${drafts===1?'':'s'}</span>`:''}`;return`<div class="projects-overview"><div><span class="section-label">${archived?'Project archive':'Project programme'}</span><h1>${heading}</h1><p>${intro}</p></div><div class="projects-summary">${summary}</div></div><div class="portfolio-timeline" style="--today:${today.toFixed(3)}%"><div class="portfolio-axis"><span class="portfolio-axis-label">${date(model.start)} — ${date(model.end)}</span><div>${axis}<b style="--position:${today.toFixed(3)}%">Today · ${date(model.today)}</b></div></div><div class="portfolio-body"><div class="portfolio-gridlines" aria-hidden="true">${grid}<b></b></div>${model.rows.map(row=>portfolioRow(row,model)).join('')}</div></div>`}
