 const brief=`A new ${workType} project. Deliverables and timing to agree.`,defaults=normaliseProjectDefaults(accountProfile?.project_defaults);
  projectFilter='current';projectBuilder={brief,notes:'',showNotes:false,showDefaults:false,defaults,mode:'setup',project:null,returnView:'projects',activateOnFinish:true,draft:suggestProjectDraft(brief,{profile:accountProfile,defaults}),saving:false,saved:false};
