function programmeIsTracked(project){if(!project?.workflow)return false;const actual=actualProgramme(project),activity=project.workflow.activity.some(item=>item.type!=='tracking_started'),progress=Object.values(project.workflow.states).some(state=>state.status!=='incomplete');return activity||progress||todayInTimeZone(project.workflow.timeZone)>=actual.start}
function openProjectBuilder(project,{returnView='project',activateOnFinish=false}={}){p=project;upgradeProject(p);const defaults=normaliseProjectDefaults(p),programmeLocked=programmeIsTracked(p),actual=actualProgramme(p),programme=programmeLocked?actual:{directionDays:p.conceptDays,makingDays:p.animationDays,reviewRounds:p.reviews,reviewDays:p.reviewDays,finishDays:p.finishDays};projectBuilder={brief:p.description,notes:'',showNotes:false,showDefaults:false,defaults,mode:'setup',project:p,returnView,activateOnFinish,programmeLocked,livePlan:programmeLocked?actual.plan:null,saved:true,saving:false,draft:{title:p.title,client:p.client,description:p.description,start:programmeLocked?actual.start:p.start,deliverableItems:p.deliverableItems.map(({name,specs})=>({name,specs})),fee:p.fee,deposit:p.deposit,paymentNote:p.paymentNote,terms:p.terms,defaults,programme}};view='builder';preview=false;render();window.scrollTo(0,0)}
function closeProjectBuilder(){clearTimeout(builderSaveTimer);const project=projectBuilder?.project,returnView=projectBuilder?.returnView;projectBuilder=null;if(returnView==='project'&&project){p=project;view='project';preview=false;render();window.scrollTo(0,0)}else projectList()}

function builderDefaultsSummary(){const defaults=projectBuilder.defaults,type=accountProfile?.work_types?.[0]||defaults.makingStageName;return`${defaults.currency} · ${defaults.deposit}% deposit · ${type} workflow`}
function builderPreviewMarkup(){
 const d=projectBuilder.draft,items=d.deliverableItems||[],programme=d.programme||{},fee=Number(d.fee)||0,deposit=Number(d.deposit??d.defaults.deposit)||0;
 const programmePreview=projectBuilder.programmeLocked?`<b>${date(projectBuilder.livePlan[0].start)} — ${date(projectBuilder.livePlan.at(-1).end)}</b><div class="builder-programme-preview">${projectBuilder.livePlan.map(stage=>`<span><i></i><b>${esc(compactStageName(stage.name))}</b><small>${date(stage.start)}${stage.end!==stage.start?' — '+date(stage.end):''}</small></span>`).join('')}</div>`:`<b>Kick-off ${date(d.start)}</b><p>${programme.directionDays??d.defaults.conceptDays} days direction · ${programme.makingDays??d.defaults.animationDays} days ${esc(d.defaults.makingStageName.toLowerCase())} · ${programme.reviewRounds??d.defaults.reviews} reviews</p>`;
 return`<article class="builder-document"><div class="builder-document-meta"><span>${esc(accountProfile?.display_name||'Your project')}</span><span>${projectBuilder.saved?'Draft saved':'Not saved yet'}</span></div><h2>${esc(d.title||'Untitled project')}</h2><p class="builder-document-client">For ${esc(d.client||'Client to confirm')}</p><p>${esc(d.description||'Add a short description.')}</p><div class="builder-document-section"><span>Programme</span>${programmePreview}</div><div class="builder-document-section"><span>Deliverables</span>${items.map(item=>`<div><b>${esc(item.name)}</b><p>${esc(item.specs||'Specifications to confirm')}</p></div>`).join('')}</div><div class="builder-document-section"><span>Payment plan</span><b>${fee?new Intl.NumberFormat('en-NZ',{style:'currency',currency:d.defaults.currency,maximumFractionDigits:0}).format(fee):'Fee to agree'} · ${deposit}% deposit</b><p>${esc(d.paymentNote)}</p></div><div class="builder-document-section"><span>Terms of engagement</span><p>${esc(d.terms)}</p></div></article>`;
}
function renderProjectBuilder(){
 const editing=!projectBuilder.activateOnFinish;document.title=`${editing?'Edit':'New'} project — Seabird`;$('#actions').innerHTML=`<button class="builder-cancel" data-builder="builder-cancel">${editing?'Back to project':'Cancel'}</button>`;
 const d=projectBuilder.draft,defaults=d.defaults,programme=d.programme||{directionDays:defaults.conceptDays,makingDays:defaults.animationDays,reviewRounds:defaults.reviews,reviewDays:defaults.reviewDays,finishDays:defaults.finishDays};
 const programmeFields=projectBuilder.programmeLocked?`<div class="builder-live-programme"><div><b>Actual project programme</b><span>${date(projectBuilder.livePlan[0].start)} — ${date(projectBuilder.livePlan.at(-1).end)}</span></div><p>This project is already underway. Its recorded dates are preserved here; use Change programme to move the remaining work.</p><div>${projectBuilder.livePlan.map(stage=>`<span><b>${esc(stage.name)}</b><small>${date(stage.start)}${stage.end!==stage.start?' — '+date(stage.end):''}</small></span>`).join('')}</div><button type="button" data-builder="change-programme">Change programme ↗</button></div>`:`<div class="pair"><label>Kick-off<input name="start" type="date" value="${d.start}" required></label><label>Direction days<input name="directionDays" type="number" min="1" max="90" value="${programme.directionDays}"></label></div><div class="pair"><label>${esc(defaults.makingStageName)} days<input name="makingDays" type="number" min="1" max="90" value="${programme.makingDays}"></label><label>Review rounds<input name="reviewRounds" type="number" min="1" max="6" value="${programme.reviewRounds}"></label></div>`;
 const setup=`<form class="builder-setup" id="builder-live-form"><span class="builder-eyebrow">${editing?'Edit project':'New project'}</span><h1>${editing?'Edit the project as it changes.':'Build the project as you go.'}</h1><p class="builder-explainer">${editing?'Changes save to the working project. Accepted client versions stay unchanged until you publish a new version.':'Every answer updates the project beside you. Seabird starts with a useful guess; change only what needs changing.'}</p><div class="builder-review-section"><span class="builder-section-label">Starting point</span><label>Project brief<textarea name="brief" maxlength="10000">${esc(projectBuilder.brief)}</textarea></label><div class="builder-source-actions"><button type="button" data-builder="notes">${projectBuilder.showNotes?'Hide notes':'Paste client notes'}</button><button type="button" data-builder="document">Add text document</button><input id="builder-document" class="sr-only" type="file" accept=".txt,.md,text/plain,text/markdown"></div>${projectBuilder.showNotes?`<label>Client notes <span class="optional">Optional</span><textarea name="notes" maxlength="10000">${esc(projectBuilder.notes)}</textarea></label>`:''}<button type="button" data-builder="ai">Improve guesses with AI</button><p class="builder-private">Only sent when you choose AI. Source text is not retained by Seabird.</p></div><div class="builder-review-section"><span class="builder-section-label">1 · Project identity</span><label>Project name<input name="title" maxlength="200" required value="${esc(d.title)}"></label><label>Client<input name="client" maxlength="200" required value="${esc(d.client)}"></label><label>Short description<textarea name="description" maxlength="10000">${esc(d.description)}</textarea></label></div><div class="builder-review-section"><span class="builder-section-label">2 · Programme</span>${programmeFields}</div><div class="builder-review-section"><span class="builder-section-label">3 · Deliverables</span><div class="builder-deliverables">${d.deliverableItems.map((item,index)=>`<div class="builder-deliverable" data-builder-item="${index}"><label>Name<input name="deliverable-${index}" maxlength="200" value="${esc(item.name)}"></label><label>Specifications<textarea name="specs-${index}" maxlength="2000">${esc(item.specs)}</textarea></label>${d.deliverableItems.length>1?`<button type="button" data-builder-remove="${index}">Remove</button>`:''}</div>`).join('')}</div><button type="button" data-builder="add-deliverable">+ Add deliverable</button></div><div class="builder-review-section"><span class="builder-section-label">4 · Payment plan</span><div class="pair"><label>Fee (${defaults.currency})<input name="fee" type="number" min="0" max="1000000000" value="${d.fee}"></label><label>Deposit (%)<input name="deposit" type="number" min="0" max="100" value="${d.deposit??defaults.deposit}"></label></div><label>Payment wording<textarea name="paymentNote" maxlength="10000">${esc(d.paymentNote)}</textarea></label></div><div class="builder-review-section"><span class="builder-section-label">5 · Terms of engagement</span><label>Working terms<textarea name="terms" maxlength="10000">${esc(d.terms)}</textarea></label></div><button class="primary builder-finish">${editing?'Done editing':'Start this project'}</button><p class="builder-status" role="status">${projectBuilder.saving?'Saving draft…':projectBuilder.saved?'Draft saved':''}</p></form>`;
 $('#app').innerHTML=`<section class="project-builder-live"><div class="builder-mobile-switch"><button data-builder="mode-setup" class="${projectBuilder.mode==='setup'?'is-active':''}">Setup</button><button data-builder="mode-preview" class="${projectBuilder.mode==='preview'?'is-active':''}">Preview</button></div><div class="builder-live-grid"><div class="builder-setup-pane ${projectBuilder.mode==='preview'?'is-mobile-hidden':''}">${setup}</div><div class="builder-preview-pane ${projectBuilder.mode==='setup'?'is-mobile-hidden':''}"><span class="builder-eyebrow">Live project</span>${builderPreviewMarkup()}</div></div></section>`;
 const form=$('#builder-live-form');if(form){form.addEventListener('input',()=>{syncBuilderDraft(form);projectBuilder.saved=false;refreshBuilderPreview();const status=$('.builder-status');if(status)status.textContent=builderCanSave()?'Saving draft…':'';scheduleBuilderSave()});form.onsubmit=finishProjectBuilder}
}

function syncBuilderDraft(form=$('#builder-live-form')){if(!form)return;const data=new FormData(form),d=projectBuilder.draft;projectBuilder.brief=String(data.get('brief')||projectBuilder.brief);projectBuilder.notes=String(data.get('notes')||projectBuilder.notes);for(const key of ['title','client','description','start','paymentNote','terms'])if(data.has(key))d[key]=String(data.get(key)).trim();d.fee=Number(data.get('fee'))||0;d.deposit=Math.max(0,Math.min(100,Number(data.get('deposit'))||0));if(data.has('directionDays'))d.programme={directionDays:Number(data.get('directionDays'))||d.defaults.conceptDays,makingDays:Number(data.get('makingDays'))||d.defaults.animationDays,reviewRounds:Number(data.get('reviewRounds'))||d.defaults.reviews,reviewDays:d.defaults.reviewDays,finishDays:d.defaults.finishDays};d.deliverableItems=d.deliverableItems.map((item,index)=>({name:String(data.get(`deliverable-${index}`)||item.name).trim(),specs:String(data.get(`specs-${index}`)||item.specs).trim()}));}
function builderCanSave(){const d=projectBuilder.draft;return!!(d.title.trim()&&d.client.trim()&&!/^client to confirm$/i.test(d.client.trim()))}
function refreshBuilderPreview(){const current=$('.builder-document');if(current)current.outerHTML=builderPreviewMarkup()}
let builderSaveTimer=null;function scheduleBuilderSave(){clearTimeout(builderSaveTimer);builderSaveTimer=setTimeout(()=>persistBuilderDraft().catch(error=>{const status=$('.builder-status');if(status)status.textContent=error.message}),500)}
function applyDraftToProject(project,d,{preserveProgramme=false}={}){project.title=d.title;project.client=d.client;project.description=d.description;if(preserveProgramme&&project.workflow)project.start=project.workflow.plan[0].start;else{project.start=d.start;project.conceptDays=d.programme.directionDays;project.animationDays=d.programme.makingDays;project.reviews=d.programme.reviewRounds;project.reviewDays=d.programme.reviewDays;project.finishDays=d.programme.finishDays}project.deliverableItems=d.deliverableItems.map((item,index)=>({id:project.deliverableItems[index]?.id,name:item.name||'Deliverable to confirm',specs:item.specs,status:project.deliverableItems[index]?.status||'planned'}));project.deliverables=project.deliverableItems.map(item=>item.name).join('\n');project.fee=d.fee;project.deposit=d.deposit;project.paymentNote=d.paymentNote;project.terms=d.terms;project.updatedAt=new Date().toISOString();if(!preserveProgramme&&project.workflow?.activity.every(item=>item.type==='tracking_started')){project.workflow=undefined;startTracking(project)}upgradeProject(project);const deposit=Math.round(project.fee*project.deposit)/100,end=stages(project).at(-1).end;project.paymentMilestones=[{...project.paymentMilestones[0],id:'payment-deposit',label:'Deposit to book the project',amount:deposit,dueOn:project.start},{...project.paymentMilestones[1],id:'payment-balance',label:'Before final delivery',amount:Math.max(0,project.fee-deposit),dueOn:end}];}
async function persistBuilderDraft(){const d=projectBuilder.draft;if(!builderCanSave())return;const draftVersion=JSON.stringify(d);projectBuilder.saving=true;try{if(!projectBuilder.project){const next=newProject({title:d.title,client:d.client,description:d.description,start:d.start},{defaults:d.defaults,provider:accountProfile});applyDraftToProject(next,d);projects.unshift(next);projectBuilder.project=next;p=next}else applyDraftToProject(projectBuilder.project,d,{preserveProgramme:projectBuilder.programmeLocked});await workspace.save();if(JSON.stringify(projectBuilder.draft)!==draftVersion)return;projectBuilder.saved=true;const status=$('.builder-status'),stamp=$('.builder-document-meta span:last-child');if(status)status.textContent='Draft saved';if(stamp)stamp.textContent='Draft saved'}finally{projectBuilder.saving=false}}
async function finishProjectBuilder(event){event.preventDefault();clearTimeout(builderSaveTimer);syncBuilderDraft(event.currentTarget);const status=$('.builder-status');try{await persistBuilderDraft();if(!projectBuilder.project)throw new Error('Add a project name and client first.');const activate=projectBuilder.activateOnFinish;if(activate)projectBuilder.project.lifecycle='active';save();await workspace.save();p=projectBuilder.project;projectBuilder=null;view='project';render();window.scrollTo(0,0);toast(activate?'Project started.':'Project updated.')}catch(error){status.textContent=error.message}}

async function handleBuilderAction(action){
 if(action==='builder-cancel'){clearTimeout(builderSaveTimer);if(projectBuilder.returnView==='project'){syncBuilderDraft();const status=$('.builder-status');try{await persistBuilderDraft();closeProjectBuilder()}catch(error){if(status)status.textContent=error.message}}else closeProjectBuilder();return}
 if(action==='mode-setup'||action==='mode-preview'){syncBuilderDraft();projectBuilder.mode=action.slice(5);renderProjectBuilder();return}
 if(action==='notes'){projectBuilder.showNotes=!projectBuilder.showNotes;renderProjectBuilder();if(projectBuilder.showNotes)$('#project-notes').focus();return}
 if(action==='document'){$('#builder-document').click();return}
 if(action==='add-deliverable'){syncBuilderDraft();projectBuilder.draft.deliverableItems.push({name:'Deliverable to confirm',specs:''});renderProjectBuilder();return}
 if(action==='change-programme'){syncBuilderDraft();const project=projectBuilder.project,status=$('.builder-status');try{await persistBuilderDraft();projectBuilder=null;p=project;view='project';render();window.scrollTo(0,0);openReplan()}catch(error){if(status)status.textContent=error.message}return}
 if(action==='ai'){syncBuilderDraft();const status=$('.builder-status');status.textContent='Improving the first guesses…';try{const result=await workspace.cloud.projectDraft({brief:projectBuilder.brief,notes:projectBuilder.notes,defaults:projectBuilder.defaults,profile:{work_types:accountProfile?.work_types||[]},current:projectBuilder.draft}),a=result.draft,d=projectBuilder.draft,locked=projectBuilder.programmeLocked,start=d.start,programme=d.programme;Object.assign(d,{title:a.title,client:a.client,description:a.description,start:a.start,deliverableItems:a.deliverables,fee:a.fee,deposit:a.deposit,paymentNote:a.paymentNote,terms:a.terms,programme:a.programme});if(locked){d.start=start;d.programme=programme}renderProjectBuilder();toast('AI suggestions added. Review every field.')}catch(error){status.textContent=error.message}return}
}

document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.builder){handleBuilderAction(button.dataset.builder);return}if(button.dataset.builderRemove!==undefined){syncBuilderDraft();projectBuilder.draft.deliverableItems.splice(Number(button.dataset.builderRemove),1);renderProjectBuilder();return}if(button.dataset.deliverableStatus){const item=p.deliverableItems.find(value=>value.id===button.dataset.deliverableStatus);setDeliverableStatus(p,item.id,item.status==='planned'?'ready':item.status==='ready'?'delivered':'approved');save();persistAndShareProgress('Deliverable status updated.');return}if(button.dataset.paymentStatus){const item=p.paymentMilestones.find(value=>value.id===button.dataset.paymentStatus);setPaymentStatus(p,item.id,item.status==='planned'?'requested':'paid');save();persistAndShareProgress('Payment status updated.');return}button.closest('details')?.removeAttribute('open');if(button.dataset.stage!==undefined){openStage(Number(button.dataset.stage));return}if(button.dataset.project!==undefined&&!readonly){p=projects[Number(button.dataset.project)];upgradeProject(p);view='project';preview=false;if(dialog.open)dialog.close();render();window.scrollTo(0,0);return}const a=button.dataset.action;if(a==='builder-cancel'){projectList();return}if(a==='review-pending'){sharedRecord={...sharedRecord,...sharedRecord.pending,pending:null,accepted_at:null};p=sharedRecord.project;render();return}if(a==='agreement'){showAgreement();return}if(a==='back-project'){closeAgreement();return}if(a==='download-agreement'){downloadAgreement();return}if(readonly)return;if(a==='sign-in')workspace?.signInWithGoogle();else if(a==='edit-project')openProjectBuilder(p);else if(a==='start-tracking')openTracking();else if(a==='complete-stage')finishCurrentStage();else if(a==='waiting')openWaiting();else if(a==='clear-waiting'){const status=currentStageStatus(p);clearStageWaiting(p,status.current.key);save();persistAndShareProgress('Waiting state cleared.')}else if(a==='replan')openReplan();else if(a==='variation')openVariation();else if(a==='activity')openActivity();else if(a==='complete-project'){completeProject(p);save();persistAndShareProgress('Project completed.')}else if(a==='reopen-project'){reopenProject(p);save();persistAndShareProgress('Project reopened.')}else if(a==='archive-project')setProjectArchived(true);else if(a==='restore-project')setProjectArchived(false);else if(a==='delete-project')openDeleteProject();else if(a==='private-note')openPrivateNote();else if(a==='preview'){preview=!preview;render()}else if(a==='share')share();else if(a==='projects')projectList();else if(a==='projects-current'){projectFilter='current';renderProjects()}else if(a==='projects-archived'){projectFilter='archived';renderProjects()}else if(a==='new')createProject();else if(a==='export')download('seabird-projects-backup.json',JSON.stringify(projects,null,2));else if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>2000000)throw Error();const items=JSON.parse(await file.text());if(!Array.isArray(items)||!items.length||items.length>100||!items.every(validate))throw Error();for(const item of items){upgradeProject(item);projects.push({...item,id:crypto.randomUUID(),rate:Number(item.rate)||0,days:Number(item.days)||1,costs:Number(item.costs)||0})}view='projects';save();if(dialog.open)dialog.close();toast('Backup imported')}catch{toast('This file is not a valid Seabird project backup.')}};input.click()}else if(a)edit(a)});
document.addEventListener('change',async e=>{if(e.target.id!=='builder-document')return;const file=e.target.files[0];if(!file)return;if(file.size>200000){toast('Choose a text document smaller than 200 KB.');return}try{projectBuilder.notes=[projectBuilder.notes,await file.text()].filter(Boolean).join('\n\n').slice(0,10000);projectBuilder.showNotes=true;renderProjectBuilder();toast(`${file.name} added.`)}catch{toast('Seabird could not read that document.')}});
$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',()=>location.reload());render();if(!readonly)save();

function editDeliverables(){
  const itemFields=(v)=>'<div class="deliverable-editor"><label>Item name<input class="item-name" maxlength="200" required value="'+esc(v.name)+'" placeholder="Opening title sequence — 4K master"></label><label>Technical specifications<textarea class="item-specs" maxlength="2000" placeholder="Resolution, frame rate, pixel aspect, codec / compression, colour space…">'+esc(v.specs)+'</textarea></label><button type="button" class="remove-deliverable">Remove item</button></div>';
  open('The deliverables','<p class="hint">Name each item, then add its delivery specifications. For video: square pixels, 4:2:2, Rec.709, plus resolution, frame rate and codec as needed.</p><div id="deliverable-editors">'+deliverableItems(p).map(itemFields).join('')+'</div><button type="button" id="add-deliverable">+ Add item</button>',()=>{
    const previous=deliverableItems(p),items=Array.from(document.querySelectorAll('.deliverable-editor'),(el,index)=>({id:previous[index]?.id,name:el.querySelector('.item-name').value.trim(),specs:el.querySelector('.item-specs').value.trim(),status:previous[index]?.status||'planned',...(previous[index]?.statusOn?{statusOn:previous[index].statusOn}:{})}));
    const next={...p,deliverableItems:items,deliverables:items.map(v=>v.name).join('\n')};
    if(!validate(next)){toast('Add at least one named deliverable, up to 30 items.');return}
    Object.assign(p,next);save();dialog.close();toast('Deliverables updated');
  });
  $('#add-deliverable').onclick=()=>{if(document.querySelectorAll('.deliverable-editor').length>=30){toast('You can add up to 30 items.');return}$('#deliverable-editors').insertAdjacentHTML('beforeend',itemFields({name:'',specs:''}));$('#deliverable-editors').lastElementChild.querySelector('input').focus()};
  $('#deliverable-editors').onclick=e=>{if(e.target.closest('.remove-deliverable'))e.target.closest('.deliverable-editor').remove()};
}


let agreementRequest=0,agreementSnapshot=null,agreementIssued=null;
function showAgreement(){
 agreementRequest++;agreementSnapshot=structuredClone(p);if(!readonly){const identity=providerIdentity(accountProfile);if(identity)agreementSnapshot.provider=identity}agreementIssued=sharedRecord?new Date(sharedRecord.published_at):new Date();
 $('#actions').innerHTML='<button data-action="back-project">← Back to project</button><button class="primary" data-action="download-agreement">Download PDF ↓</button>';
 $('#app').innerHTML='<section class="agreement-view"><div class="agreement-intro"><span class="section-label">THE COMPLETE PICTURE</span><h1>Your project, on paper.</h1><p>Review the full agreement below. Download a PDF when you are ready to email it for signing.</p><p class="hint">The PDF uses the same content and styling, with page breaks for printing.</p></div>'+agreementHtml(agreementSnapshot,agreementIssued)+'</section>';
 window.scrollTo(0,0);
}
function closeAgreement(){agreementRequest++;agreementSnapshot=null;render();window.scrollTo(0,0)}
async function downloadAgreement(){
 if(!agreementSnapshot)return;const request=agreementRequest,button=$('[data-action="download-agreement"]');if(button.disabled)return;
 button.disabled=true;button.textContent='Making PDF…';
 try{const snapshot=agreementSnapshot;const blob=await agreementBlob(snapshot,agreementIssued);if(request!==agreementRequest)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(snapshot.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'project')+'-agreement.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
 catch{if(request===agreementRequest)toast('Could not generate the PDF. Please try again.')}
 finally{if(request===agreementRequest){button.disabled=false;button.textContent='Download PDF ↓'}}
}
document.addEventListener('toggle',e=>{if(e.target.matches('.project-card')&&e.target.open)document.querySelectorAll('.project-card').forEach(card=>{if(card!==e.target)card.open=false})},true);

document.addEventListener('click',e=>{const button=e.target.closest('button[data-project]');if(!button||readonly)return;const project=projects[Number(button.dataset.project)];if(project?.lifecycle!=='draft')return;e.preventDefault();e.stopImmediatePropagation();openProjectBuilder(project,{returnView:'projects',activateOnFinish:true})},true);
document.addEventListener('click',e=>{const action=e.target.closest('button')?.dataset.action;if(readonly||!['complete-project','reopen-project'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='complete-project')openProjectCompletion();else{reopenProject(p);save();persistAndShareProgress('Project reopened.')}},true);

if(!readonly)workspace=mountCloud({getProjects:()=>projects,setAccount,setProfile,validate,onError:toast,setProjects:items=>{projects=items.map(upgradeProject);p=projects[0];authState='signed-in';save();}});
if(proposalToken){const refresh=()=>{if(document.visibilityState==='visible')reloadPublished().catch(()=>{})};publicRefreshTimer=setInterval(refresh,30000);document.addEventListener('visibilitychange',refresh);}
